def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 90:
                rich_count += 1
            if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 3:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive:
        return max(0.0, min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 0
    if supply <= 15:
        scarcity = 3
    elif supply <= 17:
        scarcity = 2
    elif supply <= 20:
        scarcity = 1

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2
    if day >= 8:
        urgency += 1

    pressure = scarcity + urgency + desperate_count

    if pressure <= 1:
        bid = 8.0
    elif pressure == 2:
        bid = 16.0
    elif pressure == 3:
        bid = 28.0
    elif pressure == 4:
        bid = 42.0
    elif pressure == 5:
        bid = 58.0
    elif pressure == 6:
        bid = 74.0
    else:
        bid = 88.0

    if highest_prev >= 95:
        if urgency <= 2:
            bid = min(bid, 18.0)
        else:
            bid = max(bid, 96.0)
    elif highest_prev >= 75:
        if urgency <= 1 and scarcity <= 1:
            bid = min(bid, 14.0)
        else:
            bid = max(bid, min(highest_prev + 2.0, 92.0))
    elif highest_prev > 0:
        if urgency >= 4 or scarcity >= 2:
            bid = max(bid, highest_prev + 1.5)
        else:
            bid = max(bid, avg_prev * 0.7)

    if rich_count >= 2 and urgency <= 2 and scarcity <= 1:
        bid = min(bid, 12.0)

    if budget < bid:
        bid = budget

    reserve_floor = 0.0
    if day <= 6:
        reserve_floor = 35.0
    elif day <= 8:
        reserve_floor = 15.0

    if urgency <= 2 and budget - bid < reserve_floor:
        bid = max(0.0, budget - reserve_floor)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, max(85.0, highest_prev + 3.0)))

    if budget <= 20:
        bid = budget

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        base_bid = DAILY_SALARY * 1.1
    else:
        base_bid = max(yesterday_bids) * 1.02

    if supply < 18:
        bid = max(base_bid, DAILY_SALARY * 1.3)
    elif supply < 22:
        bid = base_bid
    else:
        bid = DAILY_SALARY * 0.9

    if my_status['hp'] < 3:
        bid = max(bid, DAILY_SALARY * 1.5)

    return min(float(my_status['budget']), float(bid))
